links=[]
for source in registry:
    if source['kind'] in ['discovery','article','background_article','feed_catalog']:continue
    for b in source['business_lines']:
        links.append({'source_id':source['id'],'business_line':b,'source_kind':source['kind'],'source_name':source['name'],'source_url':source['url'],'relationship':'candidate monitoring input' if source['kind'] in ['rss','cyber_catalog','provider_incidents','disaster_declarations','market_series','regulatory_documents'] else 'public reference or business measure; scope retained','fetch_once':True})
pd.DataFrame(links).drop_duplicates(['source_id','business_line']).to_csv(DATA/'shared_source_business_mapping.csv',index=False,encoding='utf-8-sig')
# Desired measures available only internally remain data-request items, never numeric placeholders.
gaps=[]
for p in plan:
    gaps.append({'business_line':p['business_line'],'needed_internal_measures':p['internal_vulnerability_needed'],'public_gap':p['business_data_gaps'],'status':'publicly_unavailable_or_incomplete','value':None,'action':'Use public context now; request approved aggregated business-specific history from project sponsor if supplied later.'})
pd.DataFrame(gaps).to_csv(DATA/'business_internal_data_gaps.csv',index=False,encoding='utf-8-sig')
